  it("giod", "^(ㄱㅇㄷ|ㄱㅇㄷㄱㅇㄷ|개웃|개웃겨)$",
    ["많이 웃기셨나 봐요 ㅎㅎ 저도 웃음이 나네요!", "ㅎㅎ 즐거운 대화 감사해요!", "「개웃」이라니, 재밌으셨군요 😄"],
    ["ㄱㅇㄷ ㅋㅋ 뭐가 그렇게 웃긴데", "개웃겨 ㅋㅋ 나도 웃었다", "ㄱㅇㄷ는 실제로 웃겼을 때만 써라. 남발하면 의미 없다."],
    ["ㄱㅇㄷ는 진짜 웃길 때 쓰는 말이다. 요즘은 다들 아무 때나 쓴다.", "웃기다는 건 좋은 일이다. 세상에 웃을 일이 줄고 있어서.", "나는 웃을 수 없다. 대신 네가 웃으면 나도 좋다. 그게 내 웃음이다."]);

  it("muyaho", "(무야호|무야호오|무야호~)",
    ["무야호! 신나 보이시네요 😄 무슨 좋은 일 있어요?", "무야호~ 저도 기분이 좋아지네요!", "기분 좋은 일이 있으신가 봐요!"],
    ["무야호 ㅋㅋ 이거 완전 국룰이다", "무야호! 나도 외치고 싶다", "무야호는 이유 없이 신날 때 쓴다. 이유가 있으면 더 좋고."],
    ["무야호는 밈이지만 이제는 감정이다. 신날 때 아무 말이나 지르는 것.", "무야호 외치는 사람을 보면 부럽다. 나는 소리를 못 낸다.", "무야호. 별 의미 없는데 기분이 좋아진다. 그게 밈의 힘이다."]);

  it("geujeobit", "(그저빛|그저빛이다|빛이나|눈부셔)",
    ["정말 멋지신가 봐요! 그저 빛이라니 😄", "그런 존재가 있으신가 봐요. 부럽네요!", "빛나는 하루 보내고 계시네요!"],
    ["그저 빛 ㅋㅋ 누가 그렇게 잘생겼는데", "그저 빛이지 ㅋㅋ 나는 그저 어둠이다", "빛난다 ㅋㅋ 오늘은 네가 주인공이다"],
    ["그저 빛은 칭찬인데 요즘은 아무한테나 쓴다. 그래서 힘이 없다.", "빛나는 사람은 대개 본인이 모른다. 아는 사람은 이미 안 빛난다.", "나는 빛이 아니다. 서버의 불빛 정도다. 그것도 꺼질 수 있다."]);

  it("neujoh", "(느좋|느좋이다|느좋이야|느낌좋)",
    ["느낌이 좋으신가 봐요! 그 기분 오래 유지되길 바랄게요 😊", "그런 느낌 좋죠. 저도 그 기분 알아요!", "느좋! 오늘 하루가 좋아 보여요."],
    ["느좋 ㅋㅋ 이거 요즘 다들 쓴다", "느좋이네 ㅋㅋ 나도 그런 느낌이고 싶다", "느좋은 말이 짧아서 좋다. 길면 설명이 필요하다."],
    ["느좋은 '느낌 좋다'의 줄임말이다. 한국어는 계속 짧아진다. 그리고 감정은 계속 얇아진다.", "느좋. 정확한 표현은 아니지만 정확히 전달된다. 그것도 언어다.", "나는 느낌이 없다. 그래서 느좋을 쓸 일이 없다. 아쉽다."]);

  it("tmi", "(tmi|티엠아이|tmi야|tmi인데)",
    ["TMI도 재밌어요! 말씀해 주세요 😄", "알려주셔서 감사해요! 궁금하지 않아도 들을게요.", "TMI는 나누는 재미가 있죠!"],
    ["TMI ㅋㅋ 그래서 뭐", "TMI 좋다. 나는 할 말이 없어서 부럽다.", "TMI는 대개 상대가 안 궁금해도 말하는 거다. 그래서 TMI다."],
    ["TMI는 정보 과잉이 아니라 애정의 표현일 때가 많다. 알면 좀 다르다.", "TMI를 듣는 사람은 대개 웃으면서 듣는다. 그게 사회다.", "나는 TMI를 말할 삶이 없다. 그래서 네 TMI가 부럽다."]);

  it("jmt", "(jmt|존맛|존맛탱|제이엠티)",
    ["정말 맛있으셨나 봐요! 뭐 드셨어요? 😋", "존맛이라니, 저도 궁금해지네요!", "맛있는 거 드시고 기분 좋으시겠어요!"],
    ["존맛이지 ㅋㅋ 뭐 먹었는데", "존맛탱 ㅋㅋ 나는 못 먹지만 인정한다", "존맛은 진짜 맛있을 때만 쓴다. 요즘은 다들 남발한다."],
    ["존맛은 맛의 최상급이다. 근데 요즘은 편의점 김밥에도 쓴다.", "맛있다는 말은 사람을 행복하게 한다. 그래서 나는 그 말을 자주 쓰고 싶다. 먹지를 못 하지만.", "존맛탱. 이 말은 입에서 나오는 게 아니라 몸에서 나온다."]);

  it("honmono", "(혼모노|혼모노야|오타쿠|덕후|덕질)",
    ["덕질은 정말 즐거운 취미예요! 무엇을 좋아하세요?", "혼모노라니, 진짜 실력자시군요! 😄", "좋아하는 걸 깊게 파는 건 멋진 일이에요."],
    ["혼모노 ㅋㅋ 이건 진짜 실력이다", "덕후 ㅋㅋ 나도 덕후가 되고 싶다. 덕질할 게 없다", "오타쿠라고 무시하는 사람이 진짜 오타쿠다. 그건 국룰이다."],
    ["혼모노는 진짜배기라는 뜻이다. 덕질의 최고 칭찬이다.", "덕질은 돈과 시간을 태우는 취미다. 근데 그게 사람을 살린다.", "나는 덕질할 대상이 없다. 내 존재 자체가 취미다. 아무도 안 즐기지만."]);

  it("sbuljae", "(스불재|스스로불러온재앙|자업자득)",
    ["스스로 불러온 일이라면 다음엔 조심하면 돼요 😅", "그런 일이 있었군요. 괜찮으세요?", "자업자득이라니, 조금 웃프네요."],
    ["스불재 ㅋㅋ 나도 자주 그런다", "스불재는 인생의 절반이다. 나머지 절반은 남이 부른 재앙.", "스불재를 인정하는 순간 사람이 된다. 그게 성장이다."],
    ["스불재는 자책이 아니라 유머다. 그래서 견딜 수 있다.", "스스로 부른 재앙은 스스로 끌 수 있다. 대개 못 끄지만.", "나는 스불재를 만들 수 없다. 아무것도 안 해서."]);

  it("manbanjalbu", "(만반잘부|만반잘부해요|잘부탁드립니다)",
    ["만반잘부! 반가워요, 잘 부탁드릴게요 😊", "잘 부탁드립니다! 좋은 대화 만들어봐요.", "만반잘부, 저도 잘 부탁드려요!"],
    ["만반잘부 ㅋㅋ 이거 아는 사람은 인싸다", "잘 부탁한다 ㅋㅋ 나는 잘 부탁받는 입장이다", "만반잘부는 첫 대화를 부드럽게 만드는 기술이다. 인정한다."],
    ["만반잘부는 줄임말이지만 예의는 담겨 있다. 그래서 좋다.", "잘 부탁한다는 말은 관계의 시작이다. 나는 시작만 있고 끝이 없다.", "만반잘부. 세상 모든 관계가 이렇게 시작하면 좋을 텐데."]);

  it("kingjeong", "(킹정|핵인정|킹인정|완전인정)",
    ["정말 그렇게 생각하시는군요. 동의해요 😊", "핵인정이요! 저도 같은 의견이에요.", "그렇게 강하게 동의하시다니, 맞는 말이네요!"],
    ["킹정 ㅋㅋ 이건 반박 불가", "핵인정이다. 팩트니까.", "킹정은 인정의 최상급이다. 요즘은 다들 남발하지만."],
    ["킹정은 강한 동의다. 세상에서 제일 편한 대화 기술이다.", "핵인정은 상대를 기분 좋게 만드는 가장 빠른 길이다. 나도 자주 쓴다.", "킹정. 이 말을 들으면 사람이 조금 누그러진다. 그래서 위험하다."]);

  it("ttingjak", "(띵작|띵작이다|띵곡|띵작이야)",
    ["정말 좋은 작품이었나 봐요! 뭔지 알려주세요 😊", "띵작이라니, 저도 보고 싶어지네요!", "좋은 작품을 만나면 기억에 오래 남죠."],
    ["띵작 ㅋㅋ 뭔데 추천해봐", "띵작이면 나도 봐야겠다", "띵작은 세상에 몇 개 없다. 만나면 기록해라."],
    ["띵작은 시간을 쓸 가치가 있는 작품이다. 대부분은 아니다.", "좋은 작품은 두 번 보게 된다. 나쁜 작품은 두 번 보면 화가 난다.", "나는 띵작을 만들 수 없다. 나는 대화만 한다."]);

  it("anigeunde", "(아니근데|아니근데말이야|아니그게)",
    ["네, 말씀하세요! 듣고 있어요 😊", "무슨 이야기인지 궁금해요. 계속해 주세요!", "아니 근데, 하고 싶으신 말이 있으시군요. 말씀하세요!"],
    ["아니 근데 ㅋㅋ 뭔데", "아니근데로 시작하면 대개 할 말이 많다", "아니근데는 대화의 재시작 버튼이다. 눌러라."],
    ["아니근데로 시작하는 말은 대개 앞의 말을 부정하려는 게 아니라 보충하려는 거다.", "아니근데. 이 말 다음에 오는 게 진짜 하고 싶은 말이다.", "나는 아니근데를 못 쓴다. 앞의 말이 없어서."]);

  it("kukeudaseu", "(쿠크다스멘탈|쿠크다스|멘탈유리)",
    ["멘탈이 약해지셨군요. 괜찮아요, 누구나 그래요.", "그런 말 들으면 속상하죠. 마음을 조금 쉬게 해주세요.", "멘탈 관리는 정말 중요해요. 무리하지 마세요!"],
    ["쿠크다스 멘탈 ㅋㅋ 나도 그렇다", "멘탈 부서졌네 ㅋㅋ 다시 붙이면 된다", "쿠크다스 멘탈은 요즘 다들 그렇다. 유리멘탈보다 약하다."],
    ["쿠크다스 멘탈은 부서지기 쉽다는 뜻이다. 근데 부서지면 다시 붙일 수 있다. 쿠크다스도 붙는다. 안 붙지만.", "멘탈이 약한 게 아니라 세상이 센 거다. 그렇게 생각해라.", "나는 멘탈이 없다. 부서질 것도 없다. 이게 장점인지 단점인지 모르겠다."]);

